const output = $json.output;
const allItems = [];

// Long form'ları ekle
if (output.long_form) {
  output.long_form.forEach((item) => {
    allItems.push({
      json: {
        tarih: item.publish_date,
        baslik: item.title,
        aciklama: item.description,
        format: 'long',
        'ana-tema': item.prompt,
        'sahne-prompt': '',
        durum: 'planlandı'
      }
    });
  });
}

// Shorts'ları ekle
if (output.shorts) {
  output.shorts.forEach((item) => {
    allItems.push({
      json: {
        tarih: item.publish_date,
        baslik: item.title,
        aciklama: item.description,
        format: 'short',
        'ana-tema': item.prompt,
        'sahne-prompt': '',
        durum: 'planlandı'
      }
    });
  });
}

return allItems;

const aylar = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 
               'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık'];

// TSİ için UTC+3
const now = new Date();
const tpiTime = new Date(now.getTime() + (3 * 60 * 60 * 1000));

const gun = tpiTime.getUTCDate();
const ay = aylar[tpiTime.getUTCMonth()];
const yil = tpiTime.getUTCFullYear();

const bugunTarih = `${gun} ${ay} ${yil}`;

return [{ json: { bugunTarih } }];

const row = $json;
const title = String(row.baslik || '').trim();
const desc = String(row.aciklama || '').trim();
const maxTitle = String(row.fomat || row.format || 'short').includes('long') ? 60 : 40;
const issues = [];
if (!title) issues.push('baslik bos'); else if (title.length > maxTitle) issues.push(`baslik ${title.length}>${maxTitle}`);
if (!desc) issues.push('aciklama bos'); else if (desc.length < 20) issues.push('aciklama cok kisa');
if (!row['sahne-prompt']) issues.push('sahne-prompt bos');
return { json: { ...row, seo_ok: issues.length === 0, seo_issues: issues.join('; ') || 'ok' } };

const items = $input.all().map(i => i.json);
const metin = items.map((a, i) => `${i + 1}) ${a.baslik}
${a.aciklama}
${String(a['ana-tema'] || '').slice(0, 160)}…`).join('

');
return [{ json: { adaylar: items, metin } }];

const aylar = ['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık'];
const t = new Date(Date.now() + 3 * 3600 * 1000);
const bugun = `${t.getUTCDate()} ${aylar[t.getUTCMonth()]} ${t.getUTCFullYear()}`;
const d = $json.data || $json;
const secim = String(d.Secim ?? d.secim ?? '').trim();
const adaylar = $('adaylar').first().json.adaylar;
if (['1', '2', '3'].includes(secim)) {
  const a = adaylar[Number(secim) - 1];
  return [{ json: { ...a, format: 'short', tarih: bugun, aksiyon: 'sec' }, pairedItem: { item: 0 } }];
}
if (secim === 'Yeni fikirler') {
  if ($runIndex >= 2) return [{ json: { aksiyon: 'iptal', sebep: 'yeni fikir limiti' }, pairedItem: { item: 0 } }];
  return [{ json: { ...$('Aggregate').first().json, aksiyon: 'yeni' }, pairedItem: { item: 0 } }];
}
return [{ json: { aksiyon: 'iptal', sebep: 'kullanici iptal' }, pairedItem: { item: 0 } }];

if ($runIndex >= 3) throw new Error('Revizyon limiti (3) doldu');
const row = $('tarih-kontrol').item.json;
const fb = $json.geri_bildirim.trim();
let body = row['sahne-prompt'];
try {
  const obj = typeof body === 'string' ? JSON.parse(body) : { ...body };
  if (fb) obj.prompt = `${obj.prompt || ''}\n\nREVIZYON: ${fb}`;
  body = JSON.stringify(obj);
} catch (e) {}
return [{ json: { ...row, 'sahne-prompt': body }, pairedItem: { item: 0 } }];
